import xml.etree.ElementTree as ET, re, math
NS='{http://www.w3.org/2000/svg}'
t=ET.parse('output.svg'); r=t.getroot()
src=open('output.svg').read()

ids={}
for el in r.iter():
    i=el.get('id')
    if i: ids[i]=el
# 1. reference integrity
refs=set(re.findall(r'url\(#([^)]+)\)',src)) | set(re.findall(r'href="#([^"]+)"',src))
missing=refs-set(ids)
print("missing refs:", missing if missing else "none")

# 2. animateTransform on an element that also has a static transform (would be replaced)
bad=[]
for el in r.iter():
    if el.tag==NS+'animateTransform' and el.get('attributeName')=='transform':
        p=el
        # find parent
        for cand in r.iter():
            for c in cand:
                if c is el: p=cand
        if p.get('transform'): bad.append((p.get('id'), p.get('transform')))
print("animateTransform replacing a static transform:", bad if bad else "none")

# 3. keyTimes / values length consistency
for el in r.iter():
    if el.tag in (NS+'animate',NS+'animateTransform'):
        v=el.get('values'); kt=el.get('keyTimes'); ks=el.get('keySplines')
        if v and kt:
            nv=len([x for x in v.split(';') if x.strip()!='' or True])
            nk=len(kt.split(';'))
            if nv!=nk: print("  LEN MISMATCH", el.get('attributeName'), nv, nk, el.get('dur'))
            if ks and len(ks.split(';'))!=nv-1: print("  keySplines mismatch", el.get('attributeName'), len(ks.split(';')), nv-1)
            if not (kt.startswith('0') and kt.strip().endswith('1')): print("  keyTimes endpoints", kt)

# 4. keyTimes monotonic
for el in r.iter():
    if el.tag in (NS+'animate',NS+'animateTransform') and el.get('keyTimes'):
        k=[float(x) for x in el.get('keyTimes').split(';')]
        if any(k[i+1]<=k[i] for i in range(len(k)-1)): print("  NON-MONOTONIC", el.get('attributeName'), k)

# 5. numeric coordinate sanity (rough bounding check on absolute attrs)
vals=[]
for el in r.iter():
    for a in ('x','y','cx','cy','x1','y1','x2','y2','r','rx','ry'):
        v=el.get(a)
        if v is not None:
            try: vals.append((a,float(v)))
            except: pass
print("coord range x-like:", min(v for a,v in vals if a in ('x','cx','x1','x2','rx')), max(v for a,v in vals if a in ('x','cx','x1','x2','rx')))
print("coord range y-like:", min(v for a,v in vals if a in ('y','cy','y1','y2','ry')), max(v for a,v in vals if a in ('y','cy','y1','y2','ry')))

# 6. count animations
n=sum(1 for el in r.iter() if el.tag in (NS+'animate',NS+'animateTransform'))
print("animation elements:", n)
print("ids:", len(ids))
PY

