import math
S=(600.0,400.0); BOOM=(150.0,-70.0); STICK=(85.0,95.0)
def R(v,d):
    c=math.cos(math.radians(d)); s=math.sin(math.radians(d))
    return (v[0]*c-v[1]*s, v[0]*s+v[1]*c)
Ptarget=(826.0,348.0)
def err(psi):
    v=(Ptarget[0]-S[0]-R(STICK,psi)[0], Ptarget[1]-S[1]-R(STICK,psi)[1])
    return math.hypot(*v)-math.hypot(*BOOM)
vals=[(round(psi*0.5,2), round(err(psi*0.5),2)) for psi in range(-360,361)]
print("min",min(vals,key=lambda t:t[1]),"max",max(vals,key=lambda t:t[1]))
PY

